sys_script_include.script:
var MSS_Collateral_Treats_Integration = Class.create();
MSS_Collateral_Treats_Integration.prototype = {
    initialize: function() {},
    updateTaskDetails: function(colsysid) {
        var flag = false;
        try {
            // Fetch Task Record by sys_id
            var grTask = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
            if (grTask.get(colsysid)) {

                // Get sys_id of corresponding Case Record from reference field
                var caseSysId = grTask.collateral_case_id.toString();
                var grBaseTask = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
                grBaseTask.addQuery('collateral_case_id', caseSysId);
                grBaseTask.addQuery('collateral_task_type', 'Base Task');
                grBaseTask.query();

                if (grBaseTask.next()) {

                    var fieldsToCopy = [
                        // Header Data
                        'u_message_id', 'u_source', 'u_event_type', 'event_status', 'event_date_time', 'u_object_type',
                        'movement_origin', 'movement_id', 'u_objectversion',

                        // Additional Attributes
                        'instrument_class', 'settlement_date', 'direction', 'stp_status', 'movement_type', 'agreement_name',

                        // Payload Data
                        'managing_location', 'client_type_indicator', 'hpn_type', 'currency_cutoff_time', 'time_zone',
                        'u_3rd_triparty', 'custodian_name', 'asm_enable', 'currency', 'instrument_id', 'triparty_instrument_id',
                        'position_type', 'notional', 'margin_type', 'stp_details', 'csa_type', 'product_field', 'activity_sub_type', 'group_member_code', 'branch_number', 'payment_type',

                        // Additional Fields
                        'activity', 'agreement_id', 'agreement_type', 'business_line', 'counterpary_legal_name', 'created_by',
                        'created_timestamp', 'miss_cutoff', 'instrument_type', 'place_of_settlement', 'position',
                        'settlement_system', 'trade_date', 'value_date', 'new_settlement_date',

                        // Conditional Fields
                        'stp_acronym', 'dealing_position_account', 'stp_enable', 'u_assignment_team', 'rule_category'
                    ];

                    // Copy fields from Case to Task
                    fieldsToCopy.forEach(function(field) {

                        if (grTask.isValidField(field) && grBaseTask.isValidField(field)) {

                            grTask[field] = grBaseTask[field];

                        }
                    });

                    // Update Task Record
                    grTask.update();

                    flag = true;
                }

                // List of fields to copy from Case to Task
            }
            return flag;
        } catch (e) {
            gs.info('Script Include - MSS_Collateral_Treats_Integration:- updateTaskDetails error: ' + e.message);
            return false;
        }
    },

    canReject: function(taskGr) {
        if (!taskGr || !taskGr.isValidRecord()) return false;

        if (gs.hasRole('x_hsb11_mss_coll_0.collateral_checker')) return true;

        var caseId = taskGr.getValue('collateral_case_id');
        if (!caseId) return false;

        var gr = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
        gr.addQuery('collateral_case_id', caseId);
        gr.addQuery('collateral_task_type', 'Base Task');
        gr.orderByDesc('sys_created_on');
        gr.setLimit(1);
        gr.query();
        if (!gr.next()) return false;

        return gr.getValue('assigned_to') == gs.getUserID();
    },

    isNotMaker: function(taskGr) {
        var caseId = taskGr.getValue('collateral_case_id');
        if (!caseId) return false;

        var gr = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
        gr.addQuery('collateral_case_id', caseId);
        gr.addQuery('collateral_task_type', 'Base Task');
        gr.orderByDesc('sys_created_on');
        gr.setLimit(1);
        gr.query();


        if (!gr.next()) return true;
        return gr.getValue('assigned_to') !== gs.getUserID();
    },

    callTradeInput: function(token, requestBody) {
        //Declaring the keys for the repsonObj object 
        var responseObj = {
            'tradeCallResponseBody': '',
            'tradeCallStatusCode': '',
            'catchExceptionMessage': ''
        };
        try {

            var treatsOutboundToken = token;
            var rTradeCall = new sn_ws.RESTMessageV2('x_hsb11_mss_coll_0.Collateral_Treats Outbound API', 'Call trade input');
            var endpoint = gs.getProperty('x_hsb11_hsbc_mss_o.Collateral_Treats_Tradecall_Endpoint');
            rTradeCall.setEndpoint(endpoint);
            rTradeCall.setRequestHeader('Authorization', 'Bearer ' + treatsOutboundToken);
            rTradeCall.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

            rTradeCall.setRequestBody(requestBody); //encoding to UTF- 8 since the content type is URL encoded

            var tradeCallResponse = rTradeCall.executeAsync();
            tradeCallResponse.waitForResponse(gs.getProperty('x_hsb11_mss_coll_0.Treats Response SLA')); //Waiting for the response within the defined SLA
            var tradeCallResponseBody = tradeCallResponse.getBody();
            var tradeCallStatusCode = tradeCallResponse.getStatusCode();

            //Declaring the values for the keys of the responseObj

            responseObj.tradeCallResponseBody = tradeCallResponseBody;
            responseObj.tradeCallStatusCode = tradeCallStatusCode;

            return responseObj;

        } catch (ex) {
            gs.error('Script Include - MSS_Collateral_Treats_Integration:- callTradeInput() error: ' + ex.message);
            responseObj.catchExceptionMessage = ex.message;
            return responseObj;
        }
    },

    getToken: function() {

        try {

			//Fetching Treats credentials stored in system properties
            var uname = gs.getProperty('x_hsb11_mss_coll_0.Collateral_Treats_Username_for_Token');
			var pwd = gs.getProperty('x_hsb11_mss_coll_0.Collateral_Treats_Password_for_Token');

            //Preparing the requestbody with encoded username and password to be sent to Treats for fetching the Token
            var authString = 'userName=' + encodeURIComponent(uname) + '&password=' + encodeURIComponent(pwd);

            //Call to the Outbound Rest Message 
            var rAccessToken = new sn_ws.RESTMessageV2('x_hsb11_mss_coll_0.Collateral_Treats Outbound API', 'Issue connection token');
            var endpoint = gs.getProperty('x_hsb11_hsbc_mss_o.Collateral_Treats_Access_Token_Endpoint');
            rAccessToken.setEndpoint(endpoint);
            rAccessToken.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            rAccessToken.setRequestBody(authString);

            //Fetching the token value from the responsebody received from TREATS 
            var tokenResponse = rAccessToken.executeAsync();
            var tokenResponseBody = tokenResponse.getBody();
            var tokenResponseStatusCode = tokenResponse.getStatusCode();

            if (tokenResponseStatusCode == "200") {
                var parsedTokenResponseBody = JSON.parse(tokenResponseBody);
                return parsedTokenResponseBody.token;
            } else {
                return "";
            }
        } catch (ex) {
            gs.error('Script Include - MSS_Collateral_Treats_Integration:- getToken() error: ' + ex.message);
            return "";
        }
    },

    callXmattersForTreatsFailure: function(apiTaskSysID) {
        try {
            var grTreats = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            if (grTreats.get(apiTaskSysID)) {
                var colCaseID = grTreats.document_id.collateral_case_id.number.toString();
                var colTaskID = grTreats.document_id.number.toString();
                var errorCode = grTreats.error_code.toString();
                var errorResponse = grTreats.error_body.toString();
                var timeStamp = grTreats.sys_updated_on.toString();

                var alertDesc = "Collateral - Treats Integration Failure Alert:\n\nCollateral Case ID: " + colCaseID + "\nCollateral Task ID: " + colTaskID + "\nError Code: " + errorCode + "\nError Response: " + errorResponse + "\nTime Stamp: " + timeStamp;

                var createEventForTreatsIntegrationFailure = new x_hsb11_mss_coll_0.MSS_Collateral_XMatter_ITID_WidgetFailureHandler().createITIDEvent('WARNING', alertDesc, 'MSSiQubeCollateral_TreatsOutbound');
            }
        } catch (e) {
            gs.info('Script Include - MSS_Collateral_Treats_Integration:- callXmattersForTreatsFailure error: ' + e.message);
        }
    },

    type: 'MSS_Collateral_Treats_Integration'
};
